// ─────────────────────────────────────────────────────────────────────────────
// Mock Owner Context (SANDBOX_MODE=true)
// Synthetic owners (active + archived) and owned records from
// sample-payloads/hubspot-owners-and-records.json. No HubSpot calls.
// Records are grouped per owner the way the live searches return them, but
// closed deals, customer contacts and completed tasks are left in on purpose:
// the analysis node re-applies every filter.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const FIXTURE = {"_meta":{"notice":"Synthetic data only. Portal, owner IDs, user IDs, team IDs, names, emails and records are fictional placeholders.","portalId":"99000001","relativeTimes":"_relative.updatedHoursAgo is resolved to an ISO updatedAt at run time (the owner's updatedAt is used as the deactivation time).","expected":{"reassigned":{"deals":7,"contacts":4,"tasks":5},"pendingGrace":["55005"],"excluded":["55007"],"noOpenRecords":["55006","55010"]}},"coverageMapping":{"REASSIGNMENT_MAP":{"55001":{"deals":"55002","contacts":"55003","tasks":"55002"},"55008":"55010"},"TEAM_COVERAGE":{"7001":["55002"],"7002":["55003","55009"]},"BACKUP_COVERAGE_OWNER_IDS":["55002","55003"],"FALLBACK_OWNER_ID":"55009","EXCLUDED_OWNER_IDS":["55007"]},"owners":{"active":{"results":[{"id":"55002","email":"marcus.vance@example.com","type":"PERSON","firstName":"Marcus","lastName":"Vance","userId":81000002,"userIdIncludingInactive":81000002,"createdAt":"2024-02-01T09:00:00.000Z","archived":false,"teams":[{"id":"7001","name":"Enterprise AE (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":900}},{"id":"55003","email":"priya.raman@example.com","type":"PERSON","firstName":"Priya","lastName":"Raman","userId":81000003,"userIdIncludingInactive":81000003,"createdAt":"2024-02-01T09:00:00.000Z","archived":false,"teams":[{"id":"7002","name":"SMB Sales (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":900}},{"id":"55009","email":"sofia.lind@example.com","type":"PERSON","firstName":"Sofia","lastName":"Lind","userId":81000009,"userIdIncludingInactive":81000009,"createdAt":"2024-02-01T09:00:00.000Z","archived":false,"teams":[{"id":"7002","name":"SMB Sales (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":900}},{"id":"55004","email":"jordan.ellis@example.com","type":"PERSON","firstName":"Jordan","lastName":"Ellis","userId":81000004,"userIdIncludingInactive":81000004,"createdAt":"2024-02-01T09:00:00.000Z","archived":false,"teams":[{"id":"7001","name":"Enterprise AE (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":26},"active":false,"_scenario":"Owner list from a source that exposes an active flag: treated as deactivated"}]},"archived":{"results":[{"id":"55001","email":"dana.whitfield@example.com","type":"PERSON","firstName":"Dana","lastName":"Whitfield","userId":null,"userIdIncludingInactive":81000001,"createdAt":"2024-02-01T09:00:00.000Z","archived":true,"teams":[{"id":"7001","name":"Enterprise AE (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":30},"_scenario":"Deactivated 30h ago: direct per-object mapping"},{"id":"55005","email":"leo.hartmann@example.com","type":"PERSON","firstName":"Leo","lastName":"Hartmann","userId":null,"userIdIncludingInactive":81000005,"createdAt":"2024-02-01T09:00:00.000Z","archived":true,"teams":[{"id":"7002","name":"SMB Sales (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":3},"_scenario":"Deactivated 3h ago: inside the grace period"},{"id":"55006","email":"nina.brooks@example.com","type":"PERSON","firstName":"Nina","lastName":"Brooks","userId":null,"userIdIncludingInactive":81000006,"createdAt":"2024-02-01T09:00:00.000Z","archived":true,"teams":[{"id":"7002","name":"SMB Sales (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":50},"_scenario":"Deactivated, no open records"},{"id":"55007","email":"integration.user@example.com","type":"PERSON","firstName":"Integration","lastName":"User","userId":null,"userIdIncludingInactive":81000007,"createdAt":"2024-02-01T09:00:00.000Z","archived":true,"teams":[],"_relative":{"updatedHoursAgo":40},"_scenario":"Excluded service owner"},{"id":"55008","email":"omar.castillo@example.com","type":"PERSON","firstName":"Omar","lastName":"Castillo","userId":null,"userIdIncludingInactive":81000008,"createdAt":"2024-02-01T09:00:00.000Z","archived":true,"teams":[{"id":"7002","name":"SMB Sales (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":17520},"_scenario":"Deactivated 2 years ago with records left behind; mapped target 55010 is itself deactivated"},{"id":"55010","email":"grace.okafor@example.com","type":"PERSON","firstName":"Grace","lastName":"Okafor","userId":null,"userIdIncludingInactive":81000010,"createdAt":"2024-02-01T09:00:00.000Z","archived":true,"teams":[{"id":"7001","name":"Enterprise AE (synthetic)","primary":true}],"_relative":{"updatedHoursAgo":9600},"_scenario":"Deactivated, used as an (invalid) mapping target"}]}},"records":{"deals":[{"id":"8100101","_ownerId":"55001","properties":{"dealname":"Apex Logistics - Platform expansion","amount":"180000","dealstage":"contractsent","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55001"}},{"id":"8100102","_ownerId":"55001","properties":{"dealname":"Vanguard Cloud - Renewal 2027","amount":"96000","dealstage":"decisionmakerboughtin","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55001"}},{"id":"8100103","_ownerId":"55001","properties":{"dealname":"Orchid Health - Pilot","amount":"24000","dealstage":"qualifiedtobuy","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55001"}},{"id":"8100104","_ownerId":"55001","properties":{"dealname":"Summit Retail - Analytics add-on","amount":"41000","dealstage":"presentationscheduled","pipeline":"renewals","hs_is_closed":"false","hubspot_owner_id":"55001"}},{"id":"8100105","_ownerId":"55001","properties":{"dealname":"Kestrel Fintech - Closed deal","amount":"65000","dealstage":"closedwon","pipeline":"default","hs_is_closed":"true","hubspot_owner_id":"55001"}},{"id":"8100106","_ownerId":"55008","properties":{"dealname":"Harbor Freightways - Fleet module","amount":"33000","dealstage":"appointmentscheduled","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55008"}},{"id":"8100107","_ownerId":"55008","properties":{"dealname":"Brightwater Labs - Seat expansion","amount":"12000","dealstage":"qualifiedtobuy","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55008"}},{"id":"8100108","_ownerId":"55005","properties":{"dealname":"Northwind Media - Upgrade","amount":"28000","dealstage":"contractsent","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55005"}},{"id":"8100109","_ownerId":"55005","properties":{"dealname":"Lumiere Optique - New logo","amount":"54000","dealstage":"appointmentscheduled","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55005"}},{"id":"8100110","_ownerId":"55004","properties":{"dealname":"Cobalt Systems - Expansion","amount":"72000","dealstage":"presentationscheduled","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55004"}},{"id":"8100111","_ownerId":"55007","properties":{"dealname":"Sync test deal","amount":"1","dealstage":"appointmentscheduled","pipeline":"default","hs_is_closed":"false","hubspot_owner_id":"55007"}}],"contacts":[{"id":"9100101","_ownerId":"55001","properties":{"firstname":"Sarah","lastname":"Jenkins","email":"sarah.jenkins@example.com","lifecyclestage":"lead","hubspot_owner_id":"55001"}},{"id":"9100102","_ownerId":"55001","properties":{"firstname":"Ethan","lastname":"Moore","email":"ethan.moore@example.com","lifecyclestage":"marketingqualifiedlead","hubspot_owner_id":"55001"}},{"id":"9100103","_ownerId":"55001","properties":{"firstname":"Aisha","lastname":"Khan","email":"aisha.khan@example.com","lifecyclestage":"salesqualifiedlead","hubspot_owner_id":"55001"}},{"id":"9100104","_ownerId":"55001","properties":{"firstname":"Lena","lastname":"Vogel","email":"lena.vogel@example.com","lifecyclestage":"customer","hubspot_owner_id":"55001"}},{"id":"9100105","_ownerId":"55008","properties":{"firstname":"Diego","lastname":"Alvarez","email":"diego.alvarez@example.com","lifecyclestage":"opportunity","hubspot_owner_id":"55008"}},{"id":"9100106","_ownerId":"55005","properties":{"firstname":"Hannah","lastname":"Cole","email":"hannah.cole@example.com","lifecyclestage":"lead","hubspot_owner_id":"55005"}}],"tasks":[{"id":"6100101","_ownerId":"55001","properties":{"hs_task_subject":"Follow up: Apex Logistics contract redlines","hs_task_status":"NOT_STARTED","hubspot_owner_id":"55001"}},{"id":"6100102","_ownerId":"55001","properties":{"hs_task_subject":"Prep: Vanguard Cloud renewal call","hs_task_status":"IN_PROGRESS","hubspot_owner_id":"55001"}},{"id":"6100103","_ownerId":"55001","properties":{"hs_task_subject":"Send pilot recap to Orchid Health","hs_task_status":"WAITING","hubspot_owner_id":"55001"}},{"id":"6100104","_ownerId":"55001","properties":{"hs_task_subject":"Log notes: Kestrel Fintech kickoff","hs_task_status":"COMPLETED","hubspot_owner_id":"55001"}},{"id":"6100105","_ownerId":"55008","properties":{"hs_task_subject":"Call: Harbor Freightways demo","hs_task_status":"NOT_STARTED","hubspot_owner_id":"55008"}},{"id":"6100106","_ownerId":"55004","properties":{"hs_task_subject":"Draft proposal: Cobalt Systems","hs_task_status":"NOT_STARTED","hubspot_owner_id":"55004"}}]}};
const now = Date.now();
const owner = (o) => { const c = JSON.parse(JSON.stringify(o)); const h = c._relative?.updatedHoursAgo; if (Number.isFinite(h)) c.updatedAt = new Date(now - h * 3600000).toISOString(); delete c._relative; delete c._scenario; return c; };
const records = {};
for (const objectType of ['deals', 'contacts', 'tasks']) {
  for (const r of FIXTURE.records[objectType]) {
    const o = r._ownerId; records[o] = records[o] || {};
    const slot = records[o][objectType] = records[o][objectType] || { results: [], total: 0, error: null };
    slot.results.push({ id: r.id, properties: r.properties }); slot.total += 1;
  }
}
return [{ json: {
  source: 'fixture', portalId: cfg.portalId || FIXTURE._meta.portalId,
  owners: { active: FIXTURE.owners.active.results.map(owner), archived: FIXTURE.owners.archived.results.map(owner) },
  records, warnings: [], readErrors: [],
} }];

// ─────────────────────────────────────────────────────────────────────────────
// Detect Deactivated Owners (live)
// Deactivated = archived owner (GET /crm/v3/owners?archived=true) or an owner
// flagged active: false. Emits one CRM search per owner × object type.
// If either owner list fails, no searches run and the analysis aborts: target
// validation needs the active owner list.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const bad = (j) => !j || j.error || j.status === 'error';
const msg = (j) => String(j?.error?.message || j?.message || j?.error || 'no response').slice(0, 200);
let a = null; let r = null;
try { a = $('HubSpot: Get Active Owners').first().json; } catch (e) { a = null; }
try { r = $('HubSpot: Get Archived Owners').first().json; } catch (e) { r = null; }
const readErrors = []; const warnings = [];
if (bad(a)) readErrors.push(`Active owner list failed: ${msg(a)}`);
if (bad(r)) readErrors.push(`Archived owner list failed: ${msg(r)}`);
const active = bad(a) ? [] : (a.results || []);
const archived = bad(r) ? [] : (r.results || []);
if (!bad(a) && a.paging?.next) warnings.push('More than 500 active owners: only the first page was read. Coverage reps beyond it are treated as unknown.');
if (!bad(r) && r.paging?.next) warnings.push('More than 500 archived owners: only the first page was read. The rest are picked up after reassignment drains this page.');
const now = Date.now();
const excluded = new Set(cfg.excludedOwnerIds);
const inLookback = (o) => !cfg.lookbackDays || (Date.parse(o.updatedAt || '') || 0) >= now - cfg.lookbackDays * 86400000;
const candidates = [...archived, ...active.filter((o) => o.active === false)].filter((o) => !excluded.has(String(o.id)) && inLookback(o));
const PROPS = {
  deals: ['dealname', 'amount', 'dealstage', 'pipeline', 'hs_is_closed', 'hubspot_owner_id'],
  contacts: ['lifecyclestage', 'hubspot_owner_id'],
  tasks: ['hs_task_subject', 'hs_task_status', 'hubspot_owner_id'],
};
const body = (objectType, id) => {
  const owner = { propertyName: 'hubspot_owner_id', operator: 'EQ', value: String(id) };
  let filterGroups;
  if (objectType === 'deals') filterGroups = [{ filters: [owner, { propertyName: 'hs_is_closed', operator: 'EQ', value: 'false' }] }];
  else if (objectType === 'tasks') filterGroups = [{ filters: [owner, { propertyName: 'hs_task_status', operator: 'NEQ', value: 'COMPLETED' }] }];
  else filterGroups = cfg.contactExcludeLifecycleStages.length
    ? [{ filters: [owner, { propertyName: 'lifecyclestage', operator: 'NOT_IN', values: cfg.contactExcludeLifecycleStages }] }, { filters: [owner, { propertyName: 'lifecyclestage', operator: 'NOT_HAS_PROPERTY' }] }]
    : [{ filters: [owner] }];
  return { filterGroups, properties: PROPS[objectType], sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }], limit: cfg.searchPageSize };
};
const searches = readErrors.length ? [] : candidates.flatMap((o) => cfg.reassignObjects.map((objectType) => ({ ownerId: String(o.id), objectType, body: body(objectType, o.id) })));
return [{ json: { owners: { active, archived }, warnings, readErrors, searches } }];

// ─────────────────────────────────────────────────────────────────────────────
// Assemble Owner Context (live)
// Joins each search response with its owner × object request (same order).
// A failed search is kept as an error for that owner and object: those
// records are never treated as "no open records".
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const D = $('Detect Deactivated Owners').first().json;
const bad = (j) => !j || j.error || j.status === 'error';
const msg = (j) => String(j?.error?.message || j?.message || j?.error || 'no response').slice(0, 200);
let resp = [];
try { resp = $('HubSpot: Search Owned Records').isExecuted ? $('HubSpot: Search Owned Records').all() : []; } catch (e) { resp = []; }
const records = {};
D.searches.forEach((s, i) => {
  const j = resp[i]?.json;
  records[s.ownerId] = records[s.ownerId] || {};
  records[s.ownerId][s.objectType] = bad(j)
    ? { results: [], total: null, error: msg(j) }
    : { results: Array.isArray(j.results) ? j.results : [], total: Number.isFinite(j.total) ? j.total : (j.results || []).length, error: null };
});
return [{ json: { source: 'hubspot', portalId: cfg.portalId, owners: D.owners, records, warnings: D.warnings, readErrors: D.readErrors } }];

// ─────────────────────────────────────────────────────────────────────────────
// Owner Deactivation & Status Analysis
// 1. Finds deactivated owners (archived: true or active: false), minus
//    exclusions and the lookback window.
// 2. Re-applies the open-record filters to what the searches returned.
// 3. Applies the grace period and the mass-deactivation guard.
// 4. Resolves coverage per object: direct map → team pool → backup pool →
//    fallback owner → hold. Every target must be an active owner.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ctx = $input.first().json;
const now = Date.now();
const S = (v) => String(v ?? '').trim();
const nameOf = (o) => (`${S(o.firstName)} ${S(o.lastName)}`.trim() || S(o.email) || `Owner ${o.id}`);
const base = { generatedAt: new Date(now).toISOString(), portalId: ctx.portalId || '', source: ctx.source, warnings: [...(ctx.warnings || [])] };
const emptyCounts = { deactivatedOwners: 0, excludedOwners: 0, reassignOwners: 0, pendingOwners: 0, heldOwners: 0, noRecordOwners: 0, openRecords: 0, deals: 0, contacts: 0, tasks: 0, searchErrors: 0 };
const cfgErrors = [['REASSIGNMENT_MAP', cfg.reassignmentMap], ['TEAM_COVERAGE', cfg.teamCoverage]].filter(([, v]) => v && v.__invalid).map(([k]) => `${k} is not valid JSON (object expected). No records were reassigned.`);
if (cfgErrors.length) {
  return [{ json: { ...base, status: 'error', error: { kind: 'config', messages: cfgErrors }, owners: [], excludedOwners: [], activeOwners: {}, counts: emptyCounts, massGuard: { tripped: false } } }];
}
if ((ctx.readErrors || []).length) {
  return [{ json: { ...base, status: 'error', error: { kind: 'owner_read', messages: ctx.readErrors }, owners: [], excludedOwners: [], activeOwners: {}, counts: emptyCounts, massGuard: { tripped: false } } }];
}
// ── Owners ───────────────────────────────────────────────────────────────────
const activeList = (ctx.owners.active || []).filter((o) => o.archived !== true && o.active !== false);
const activeOwners = Object.fromEntries(activeList.map((o) => [String(o.id), { id: String(o.id), name: nameOf(o), teams: (o.teams || []).map((t) => ({ id: String(t.id), name: t.name })) }]));
const excludedSet = new Set(cfg.excludedOwnerIds);
const inactive = [
  ...(ctx.owners.archived || []).map((o) => ({ ...o, _source: 'archived' })),
  ...(ctx.owners.active || []).filter((o) => o.active === false && o.archived !== true).map((o) => ({ ...o, _source: 'active_flag' })),
];
const seen = new Set(); const excludedOwners = []; const candidates = [];
for (const o of inactive) {
  const id = String(o.id); if (seen.has(id)) continue; seen.add(id);
  const at = Date.parse(o.updatedAt || '') || null;
  if (excludedSet.has(id)) { excludedOwners.push({ ownerId: id, name: nameOf(o), reason: 'excluded_owner' }); continue; }
  if (cfg.lookbackDays && (!at || at < now - cfg.lookbackDays * 86400000)) { excludedOwners.push({ ownerId: id, name: nameOf(o), reason: 'outside_lookback' }); continue; }
  candidates.push({ o, id, at });
}
// ── Routing helpers ──────────────────────────────────────────────────────────
const map = cfg.reassignmentMap && typeof cfg.reassignmentMap === 'object' ? cfg.reassignmentMap : {};
const teamCoverage = cfg.teamCoverage && typeof cfg.teamCoverage === 'object' ? cfg.teamCoverage : {};
const toList = (v) => (Array.isArray(v) ? v : (v === undefined || v === null || v === '' ? [] : [v])).map((x) => S(x)).filter(Boolean);
function validPool(ids, selfId) {
  const ok = []; const bad = [];
  for (const id of ids) { if (id === selfId) bad.push({ id, why: 'is the deactivated owner' }); else if (!activeOwners[id]) bad.push({ id, why: 'is not an active owner' }); else if (excludedSet.has(id)) bad.push({ id, why: 'is excluded' }); else if (!ok.includes(id)) ok.push(id); }
  return { ok, bad };
}
function route(o, id, objectType) {
  const skipped = [];
  const entry = map[id];
  const direct = entry && typeof entry === 'object' && !Array.isArray(entry) ? (entry[objectType] ?? entry.default) : entry;
  const levels = [
    ['direct_map', toList(direct), `owner:${id}:${objectType}`],
    ...((o.teams || []).slice().sort((a, b) => Number(Boolean(b.primary)) - Number(Boolean(a.primary))).map((t) => [`team_pool`, toList(teamCoverage[String(t.id)]), `team:${t.id}`, t.name])),
    ['backup_pool', cfg.backupCoverageOwnerIds, 'backup'],
    ['fallback_owner', toList(cfg.fallbackOwnerId), 'fallback'],
  ];
  for (const [level, ids, poolKey, label] of levels) {
    if (!ids.length) continue;
    const { ok, bad } = validPool(ids, id);
    for (const b of bad) skipped.push(`${level === 'team_pool' ? `team ${label || ''}`.trim() : level.replace(/_/g, ' ')} target ${b.id} ${b.why}`);
    if (ok.length) return { level, pool: ok, poolKey, label: label || null, skipped };
  }
  return { level: 'none', pool: [], poolKey: null, label: null, skipped };
}
// ── Open-record filters (defence in depth; live searches already filter) ──────
const excludeStages = new Set(cfg.dealExcludeStages);
const excludeLifecycle = new Set(cfg.contactExcludeLifecycleStages);
const isOpen = {
  deals: (p) => S(p.hs_is_closed).toLowerCase() !== 'true' && !excludeStages.has(S(p.dealstage).toLowerCase()),
  contacts: (p) => !excludeLifecycle.has(S(p.lifecyclestage).toLowerCase()),
  tasks: (p) => S(p.hs_task_status).toUpperCase() !== 'COMPLETED',
};
const label = {
  deals: (r) => (cfg.showRecordNames && r.properties?.dealname ? r.properties.dealname : `Deal ${r.id}`),
  contacts: (r) => `Contact ${r.id}`,
  tasks: (r) => (cfg.showRecordNames && r.properties?.hs_task_subject ? r.properties.hs_task_subject : `Task ${r.id}`),
};
// ── Per-owner analysis ───────────────────────────────────────────────────────
const owners = [];
for (const { o, id, at } of candidates) {
  const objects = {}; const notes = []; let open = 0; let errors = 0;
  for (const objectType of cfg.reassignObjects) {
    const slot = ctx.records?.[id]?.[objectType] || { results: [], total: 0, error: null };
    const rows = (slot.results || []).filter((r) => S(r.properties?.hubspot_owner_id) === id);
    const keep = rows.filter((r) => isOpen[objectType](r.properties || {}));
    const shown = (slot.results || []).length;
    const remaining = Number.isFinite(slot.total) ? Math.max(0, slot.total - shown) : 0;
    const rt = keep.length || remaining ? route(o, id, objectType) : null;
    if (rt) for (const s of rt.skipped) if (!notes.includes(s)) notes.push(s);
    if (slot.error) errors += 1;
    objects[objectType] = {
      openCount: keep.length, remaining, filteredOut: rows.length - keep.length + ((slot.results || []).length - rows.length), error: slot.error || null,
      records: keep.map((r) => ({ id: String(r.id), label: label[objectType](r), amount: objectType === 'deals' ? Number(r.properties?.amount) || 0 : undefined })),
      route: rt ? { level: rt.level, pool: rt.pool, poolKey: rt.poolKey, teamName: rt.label } : null,
    };
    open += keep.length;
  }
  const hours = at ? (now - at) / 3600000 : null;
  let state;
  if (!open && !errors && !Object.values(objects).some((x) => x.remaining)) state = 'no_open_records';
  else if (cfg.gracePeriodHours && hours !== null && hours < cfg.gracePeriodHours) state = 'pending_grace';
  else if (!open) state = errors ? 'search_failed' : 'no_open_records';
  else if (Object.values(objects).some((x) => x.openCount && x.route?.level === 'none')) state = Object.values(objects).some((x) => x.openCount && x.route?.level !== 'none') ? 'reassign_partial' : 'held_no_coverage';
  else state = 'reassign';
  if (errors) notes.push(`${errors} record search${errors > 1 ? 'es' : ''} failed: those records are not counted and will be retried next run`);
  owners.push({
    ownerId: id, name: nameOf(o), email: cfg.showOwnerEmail ? S(o.email) : undefined, source: o._source, teams: (o.teams || []).map((t) => t.name).filter(Boolean),
    deactivatedAt: at ? new Date(at).toISOString() : null, hoursSinceDeactivation: hours === null ? null : Math.round(hours * 10) / 10,
    graceEndsAt: state === 'pending_grace' ? new Date(at + cfg.gracePeriodHours * 3600000).toISOString() : null,
    state, openRecords: open, objects, notes,
  });
}
// ── Mass-deactivation guard ──────────────────────────────────────────────────
// Counts only owners deactivated within MASS_DEACTIVATION_WINDOW_HOURS: a sudden
// wave (SSO or SCIM mishap, bulk offboarding) is held; an old backlog is not.
const acting = owners.filter((x) => x.state === 'reassign' || x.state === 'reassign_partial');
const recent = acting.filter((x) => x.hoursSinceDeactivation !== null && x.hoursSinceDeactivation <= cfg.massDeactivationWindowHours);
const massGuard = { tripped: cfg.massDeactivationThreshold > 0 && recent.length > cfg.massDeactivationThreshold, actingOwners: recent.length, threshold: cfg.massDeactivationThreshold, windowHours: cfg.massDeactivationWindowHours };
if (massGuard.tripped) for (const x of acting) { x.state = 'held_mass_deactivation'; x.notes.push(`${recent.length} owners deactivated within ${cfg.massDeactivationWindowHours}h need reassignment (threshold ${cfg.massDeactivationThreshold}): held for review`); }
const order = { reassign: 0, reassign_partial: 1, held_mass_deactivation: 2, held_no_coverage: 3, search_failed: 4, pending_grace: 5, no_open_records: 6 };
owners.sort((a, b) => order[a.state] - order[b.state] || b.openRecords - a.openRecords);
const sum = (t) => owners.filter((x) => x.state.startsWith('reassign')).reduce((n, x) => n + (x.objects[t] && x.objects[t].route && x.objects[t].route.level !== 'none' ? x.objects[t].openCount : 0), 0);
const counts = {
  deactivatedOwners: owners.length + excludedOwners.length, excludedOwners: excludedOwners.length,
  reassignOwners: owners.filter((x) => x.state.startsWith('reassign')).length, pendingOwners: owners.filter((x) => x.state === 'pending_grace').length,
  heldOwners: owners.filter((x) => x.state.startsWith('held')).length, noRecordOwners: owners.filter((x) => x.state === 'no_open_records').length,
  openRecords: owners.reduce((n, x) => n + x.openRecords, 0), deals: sum('deals'), contacts: sum('contacts'), tasks: sum('tasks'),
  searchErrors: owners.reduce((n, x) => n + Object.values(x.objects).filter((y) => y.error).length, 0),
};
const status = massGuard.tripped || counts.heldOwners ? 'action_required' : (counts.deals + counts.contacts + counts.tasks ? 'reassignment_due' : 'clear');
return [{ json: { ...base, status, error: null, owners, excludedOwners, activeOwners, counts, massGuard } }];

// ─────────────────────────────────────────────────────────────────────────────
// Record Reassignment Execution Builder
// Assigns every open record of a "reassign" owner to a coverage rep:
// a single target, or round-robin across a pool (cursor kept per pool in
// workflow memory, production only). Builds batch update payloads of ≤ 100
// inputs per object type, a rollback list and the per-owner allocation.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const A = $input.first().json;
const persist = !cfg.sandboxMode && !['manual', 'test'].includes(cfg.executionMode);
const mem = persist ? ($getWorkflowStaticData('global').ownerSentinel || {}) : {};
const cursors = { ...(mem.rrCursors || {}) };
const assignments = []; const deferred = [];
let budget = cfg.maxReassignmentsPerRun;
for (const owner of A.owners.filter((o) => o.state === 'reassign' || o.state === 'reassign_partial')) {
  owner.allocation = {};
  for (const objectType of cfg.reassignObjects) {
    const ob = owner.objects[objectType];
    if (!ob || !ob.openCount || !ob.route || ob.route.level === 'none') continue;
    const alloc = owner.allocation[objectType] = { level: ob.route.level, teamName: ob.route.teamName, targets: {}, deferred: 0 };
    for (const rec of ob.records.slice().sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }))) {
      if (budget <= 0) { alloc.deferred += 1; deferred.push({ objectType, recordId: rec.id, fromOwnerId: owner.ownerId }); continue; }
      const pool = ob.route.pool; const key = ob.route.poolKey;
      const i = (cursors[key] || 0) % pool.length;
      const to = pool[i]; cursors[key] = (i + 1) % pool.length;
      assignments.push({ objectType, recordId: rec.id, label: rec.label, fromOwnerId: owner.ownerId, toOwnerId: to, level: ob.route.level });
      alloc.targets[to] = (alloc.targets[to] || 0) + 1; budget -= 1;
    }
  }
}
const batches = [];
for (const objectType of cfg.reassignObjects) {
  const rows = assignments.filter((a) => a.objectType === objectType);
  for (let i = 0; i < rows.length; i += 100) {
    const chunk = rows.slice(i, i + 100);
    batches.push({
      objectType, batch: Math.floor(i / 100) + 1, recordIds: chunk.map((a) => a.recordId),
      body: { inputs: chunk.map((a) => ({ id: a.recordId, properties: { hubspot_owner_id: a.toOwnerId, ...(cfg.previousOwnerProperty && cfg.previousOwnerObjects.includes(objectType) ? { [cfg.previousOwnerProperty]: a.fromOwnerId } : {}) } })) },
    });
  }
}
const rollback = cfg.reassignObjects.map((objectType) => ({ objectType, endpoint: `/crm/v3/objects/${objectType}/batch/update`,
  inputs: assignments.filter((a) => a.objectType === objectType).map((a) => ({ id: a.recordId, properties: { hubspot_owner_id: a.fromOwnerId } })) })).filter((r) => r.inputs.length);
return [{ json: {
  ...A, assignments, deferred, batches, rollback, nextCursors: cursors,
  plannedCount: assignments.length, writeAllowed: cfg.reassignmentEnabled && batches.length > 0,
} }];

// ─────────────────────────────────────────────────────────────────────────────
// Collect Reassignment Results
// Pairs every batch response with its request (same order). HubSpot answers
// a partial failure with 207 and an errors[] list; a full failure arrives as
// an error item. Round-robin cursors are saved only after a successful write.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const B = $('Record Reassignment Execution Builder').first().json;
const reqs = $('Emit Update Batches').all().map((i) => i.json);
const resps = $input.all().map((i) => i.json);
const updated = new Set(); const failures = [];
reqs.forEach((q, i) => {
  const r = resps[i] || {};
  if (r.error || r.status === 'error') { failures.push({ objectType: q.objectType, batch: q.batch, count: q.recordIds.length, recordIds: q.recordIds, message: String(r.error?.message || r.message || r.error || 'request failed').slice(0, 200) }); return; }
  const ok = new Set((r.results || []).map((x) => String(x.id)));
  for (const id of ok) updated.add(`${q.objectType}:${id}`);
  const errIds = new Set();
  for (const e of r.errors || []) for (const id of (e.context?.ids || [])) errIds.add(String(id));
  const missing = q.recordIds.filter((id) => !ok.has(id));
  if (missing.length) failures.push({ objectType: q.objectType, batch: q.batch, count: missing.length, recordIds: missing, message: String((r.errors || [])[0]?.message || 'not confirmed in the response').slice(0, 200) });
});
const assignments = B.assignments.map((a) => ({ ...a, result: updated.has(`${a.objectType}:${a.recordId}`) ? 'updated' : 'failed' }));
const persist = !cfg.sandboxMode && !['manual', 'test'].includes(cfg.executionMode);
if (persist && updated.size) {
  const store = $getWorkflowStaticData('global');
  store.ownerSentinel = { ...(store.ownerSentinel || {}), rrCursors: B.nextCursors, lastWriteAt: new Date().toISOString() };
}
return [{ json: { updated: updated.size, failed: assignments.filter((a) => a.result === 'failed').length, failures, assignments } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Slack Alert (Block Kit)
// Deactivated owners, records reallocated per object and target, pending and
// held owners, error log, links to HubSpot users settings and to records.
// Repeat suppression: an unchanged state (same owners, states and counts) is
// not re-posted in production unless records were written in this run.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const B = $('Record Reassignment Execution Builder').first().json;
let R = null; try { R = $('Collect Reassignment Results').isExecuted ? $('Collect Reassignment Results').first().json : null; } catch (e) { R = null; }
const persist = !cfg.sandboxMode && !['manual', 'test'].includes(cfg.executionMode);
const mem = persist ? ($getWorkflowStaticData('global').ownerSentinel || {}) : {};
const mode = cfg.sandboxMode ? 'sandbox' : cfg.dryRun ? 'dry_run' : !cfg.reassignmentEnabled ? 'reassignment_disabled' : 'live';
const written = Boolean(R);
const portal = B.portalId || '';
const TYPE = { deals: '0-3', contacts: '0-1', tasks: '0-27' };
const NOUN = { deals: ['deal', 'deals'], contacts: ['contact', 'contacts'], tasks: ['task', 'tasks'] };
const n = (k, t) => `${k} ${NOUN[t][k === 1 ? 0 : 1]}`;
const fill = (t, o = {}) => String(t).replace(/\{appHost\}/g, cfg.appHost).replace(/\{portalId\}/g, portal).replace(/\{objectTypeId\}/g, o.typeId || '').replace(/\{recordId\}/g, o.id || '');
const recUrl = (t, id) => (portal ? fill('https://{appHost}/contacts/{portalId}/record/{objectTypeId}/{recordId}', { typeId: TYPE[t], id }) : null);
const who = (id) => B.activeOwners[id]?.name || `Owner ${id}`;
const clip = (s, k) => (s.length > k ? `${s.slice(0, k - 1)}…` : s);
const LEVEL = { direct_map: 'direct map', team_pool: 'team pool', backup_pool: 'backup pool', fallback_owner: 'fallback owner' };
const result = (a) => (R ? (R.assignments.find((x) => x.objectType === a.objectType && x.recordId === a.recordId)?.result || 'failed') : 'planned');
const fp = JSON.stringify({ mode, status: B.status, owners: B.owners.filter((o) => o.state !== 'no_open_records').map((o) => [o.ownerId, o.state, o.openRecords]), err: B.error?.kind || null });
const interesting = B.status === 'error' || B.owners.some((o) => o.state !== 'no_open_records');
let alert;
if (B.status === 'error') alert = { needed: B.error.kind === 'config' || cfg.alertOnReadFailure, reason: B.error.kind === 'config' ? 'config_invalid' : 'owner_read_failed' };
else if (written) alert = { needed: true, reason: R.failed ? 'reassigned_with_errors' : 'reassigned' };
else if (!interesting) alert = { needed: cfg.notifyWhenClear, reason: 'clear' };
else if (persist && cfg.suppressRepeatAlerts && mem.lastAlertFingerprint === fp) alert = { needed: false, reason: 'repeat_suppressed' };
else alert = { needed: true, reason: B.massGuard.tripped ? 'mass_deactivation_hold' : (B.plannedCount ? 'reassignment_planned' : 'attention_needed') };

const blocks = [];
const verb = written ? 'reassigned' : (mode === 'live' ? 'to reassign' : 'would be reassigned');
if (B.status === 'error') {
  blocks.push({ type: 'header', text: { type: 'plain_text', text: B.error.kind === 'config' ? '⚠️ Owner deactivation sentinel: invalid routing configuration' : '⚠️ Owner deactivation sentinel could not run', emoji: true } });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(`${B.error.messages.map((m) => `• ${m}`).join('\n')}\n\nNo records were checked or reassigned, so this is not an all-clear.`, 2900) } });
} else {
  const ok = R ? R.updated : B.plannedCount;
  const head = B.massGuard.tripped ? `⛔ ${B.massGuard.actingOwners} owners deactivated within ${B.massGuard.windowHours}h: reassignment held`
    : written ? `🔁 ${ok} record${ok === 1 ? '' : 's'} reassigned from ${B.counts.reassignOwners} deactivated owner${B.counts.reassignOwners === 1 ? '' : 's'}${R.failed ? ` · ${R.failed} failed` : ''}`
    : B.plannedCount ? `🔁 ${B.plannedCount} records ${verb} from ${B.counts.reassignOwners} deactivated owner${B.counts.reassignOwners === 1 ? '' : 's'}`
    : '👀 Deactivated owners need attention';
  blocks.push({ type: 'header', text: { type: 'plain_text', text: clip(head, 150), emoji: true } });
  const tag = { sandbox: '_Sandbox: synthetic data, nothing changed._', dry_run: '_Dry run: nothing changed in HubSpot._', reassignment_disabled: '_REASSIGNMENT_ENABLED=false: nothing changed in HubSpot._', live: '' }[mode];
  const c = B.counts;
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `${tag ? `${tag}\n` : ''}*${c.deactivatedOwners} deactivated owners* · ${c.reassignOwners} with open records · ${c.pendingOwners} in grace period · ${c.heldOwners} held · ${c.noRecordOwners} with nothing open · ${c.excludedOwners} excluded${B.warnings.length ? `\n${B.warnings.map((w) => `⚠️ ${w}`).join('\n')}` : ''}` } });
  let shown = 0;
  for (const o of B.owners.filter((x) => x.state !== 'no_open_records')) {
    if (shown >= 15) break; shown += 1;
    const since = o.hoursSinceDeactivation === null ? '' : o.hoursSinceDeactivation < 48 ? ` · deactivated ${Math.round(o.hoursSinceDeactivation)}h ago` : ` · deactivated ${Math.round(o.hoursSinceDeactivation / 24)}d ago`;
    const title = `*${o.name}* (owner ${o.ownerId}${o.email ? `, ${o.email}` : ''})${o.teams.length ? ` · ${o.teams.join(', ')}` : ''}${since}`;
    const lines = [];
    if (o.state.startsWith('reassign')) {
      for (const t of cfg.reassignObjects) {
        const al = o.allocation?.[t];
        const ob = o.objects[t];
        if (al) {
          const mine = B.assignments.filter((a) => a.fromOwnerId === o.ownerId && a.objectType === t);
          const failed = mine.filter((a) => result(a) === 'failed').length;
          const tg = Object.entries(al.targets).map(([id, k]) => (Object.keys(al.targets).length > 1 ? `${who(id)} ×${k}` : who(id))).join(', ');
          const links = mine.slice(0, cfg.sampleLinksPerObject).map((a) => { const u = recUrl(t, a.recordId); return u ? `<${u}|${a.label}>` : a.label; }).join(', ');
          lines.push(`• *${n(mine.length, t)}* ${verb} → ${tg} _(${al.teamName ? `${al.teamName} ` : ''}${LEVEL[al.level]})_${failed ? ` · ❌ ${failed} failed` : ''}${links ? `\n   ${links}${mine.length > cfg.sampleLinksPerObject ? ` +${mine.length - cfg.sampleLinksPerObject} more` : ''}` : ''}`);
          if (al.deferred) lines.push(`   _${al.deferred} more held back by MAX_REASSIGNMENTS_PER_RUN; next run continues_`);
        } else if (ob?.openCount && ob.route?.level === 'none') lines.push(`• ⛔ *${n(ob.openCount, t)}*: no active coverage rep. Set REASSIGNMENT_MAP, TEAM_COVERAGE, BACKUP_COVERAGE_OWNER_IDS or FALLBACK_OWNER_ID.`);
        if (ob?.remaining) lines.push(`   _+${ob.remaining} more open ${NOUN[t][1]} beyond this run's search page; next run continues_`);
      }
    } else {
      const parts = cfg.reassignObjects.filter((t) => o.objects[t]?.openCount).map((t) => n(o.objects[t].openCount, t));
      const lead = { pending_grace: `⏳ ${parts.join(', ')} waiting: grace period ends ${String(o.graceEndsAt).slice(0, 16).replace('T', ' ')} UTC`,
        held_mass_deactivation: `⛔ ${parts.join(', ')} held by the mass-deactivation guard. Review, then raise MASS_DEACTIVATION_THRESHOLD or reassign in HubSpot.`,
        held_no_coverage: `⛔ ${parts.join(', ')} held: no active coverage rep. Set REASSIGNMENT_MAP, TEAM_COVERAGE, BACKUP_COVERAGE_OWNER_IDS or FALLBACK_OWNER_ID.`,
        search_failed: '❌ Record searches failed, so open records are unknown.' }[o.state];
      if (lead) lines.push(lead);
    }
    for (const note of o.notes) lines.push(`   ⚠️ ${note}`);
    blocks.push({ type: 'divider' }, { type: 'section', text: { type: 'mrkdwn', text: clip(`${title}\n${lines.join('\n')}`, 2900) } });
  }
  const errs = [...(R?.failures || []).map((f) => `• ${n(f.count, f.objectType)} (batch ${f.batch}): ${f.message}`),
    ...B.owners.flatMap((o) => cfg.reassignObjects.filter((t) => o.objects[t]?.error).map((t) => `• Search ${t} for owner ${o.ownerId}: ${o.objects[t].error}`))];
  if (errs.length) blocks.push({ type: 'divider' }, { type: 'section', text: { type: 'mrkdwn', text: clip(`*Error log*\n${errs.slice(0, 12).join('\n')}${errs.length > 12 ? `\n_+${errs.length - 12} more in the audit log_` : ''}`, 2900) } });
}
if (portal) blocks.push({ type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Users & teams settings' }, url: fill(cfg.usersSettingsUrlTemplate) }] });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `Portal ${portal || 'n/a'} · mode ${mode} · run ${cfg.runId}` }] });
const text = B.status === 'error' ? 'Owner deactivation sentinel could not run' : `Owner deactivation: ${R ? R.updated : B.plannedCount} records ${verb}`;
return [{ json: { message: { text, blocks: blocks.slice(0, 49) }, alert, fingerprint: fp, mode, slackAllowed: cfg.sendSlackAlerts && alert.needed } }];

// Collect Slack Results: Slack incoming webhooks answer "ok" (text) on success.
const r = $input.first().json;
const ok = !r.error && (r.data === undefined || String(r.data).trim() === 'ok' || r.ok === true);
return [{ json: { sent: ok ? 1 : 0, failed: ok ? 0 : 1, error: ok ? null : String(r.error?.message || r.error || r.data || 'unknown').slice(0, 200) } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Run Summary & Record State
// JSON for ALERT_WEBHOOK_URL (HRIS / IT offboarding, BI, ticketing): every
// reassignment with from/to owner and result, plus the rollback payloads.
// The alert fingerprint is saved (production only) when the alert was
// delivered or not needed, so an undelivered alert is retried next run.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const B = $('Record Reassignment Execution Builder').first().json;
const L = $('Build Slack Alert').first().json;
let R = null; try { R = $('Collect Reassignment Results').isExecuted ? $('Collect Reassignment Results').first().json : null; } catch (e) { R = null; }
let sl = null; try { sl = $('Collect Slack Results').isExecuted ? $('Collect Slack Results').first().json : null; } catch (e) { sl = null; }
const delivered = Boolean(sl && sl.sent);
const persist = !cfg.sandboxMode && !['manual', 'test'].includes(cfg.executionMode);
let recorded = false;
if (persist && B.status !== 'error' && (!L.alert.needed || delivered)) {
  const store = $getWorkflowStaticData('global');
  store.ownerSentinel = { ...(store.ownerSentinel || {}), lastAlertFingerprint: L.fingerprint, lastRunAt: B.generatedAt };
  recorded = true;
}
const res = (a) => (R ? (R.assignments.find((x) => x.objectType === a.objectType && x.recordId === a.recordId)?.result || 'failed') : 'planned');
const body = {
  event: 'hubspot.owner_deactivation.run', runId: cfg.runId, generatedAt: B.generatedAt, portalId: B.portalId || null, mode: L.mode, status: B.status, error: B.error,
  counts: B.counts, massGuard: B.massGuard, updated: R ? R.updated : 0, failed: R ? R.failed : 0,
  owners: B.owners.map((o) => ({ owner_id: o.ownerId, state: o.state, deactivated_at: o.deactivatedAt, open_records: o.openRecords, grace_ends_at: o.graceEndsAt })),
  reassignments: B.assignments.map((a) => ({ object_type: a.objectType, record_id: a.recordId, from_owner_id: a.fromOwnerId, to_owner_id: a.toOwnerId, route: a.level, result: res(a) })),
  rollback: R && R.updated ? B.rollback : [],
};
const sendAllowed = cfg.webhookEnabled && (L.alert.needed || cfg.notifyOnEveryRun);
return [{ json: { body, sendAllowed, recorded, delivered } }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final record on every path: outcome, safety flags, per-owner state and
// routing, every reassignment with its result, rollback payloads, delivery.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const B = $('Record Reassignment Execution Builder').first().json;
const L = $('Build Slack Alert').first().json;
const S = $('Build Run Summary').first().json;
let R = null; try { R = $('Collect Reassignment Results').isExecuted ? $('Collect Reassignment Results').first().json : null; } catch (e) { R = null; }
let sl = null; try { sl = $('Collect Slack Results').isExecuted ? $('Collect Slack Results').first().json : null; } catch (e) { sl = null; }
let wh = 'not_sent';
try { if ($('Webhook: Post Run Summary').isExecuted) { const r = $('Webhook: Post Run Summary').first().json; wh = r.error ? `failed: ${String(r.error.message || r.error).slice(0, 120)}` : 'sent'; } } catch (e) { wh = 'not_sent'; }
let outcome;
if (B.status === 'error') outcome = B.error.kind === 'config' ? 'config_invalid' : 'owner_read_failed';
else if (B.massGuard.tripped) outcome = 'held_mass_deactivation';
else if (R) outcome = R.failed ? (R.updated ? 'reassigned_with_errors' : 'reassignment_failed') : 'reassigned';
else if (B.plannedCount) outcome = { sandbox: 'reassignment_planned_sandbox', dry_run: 'reassignment_planned_dry_run', reassignment_disabled: 'reassignment_planned_disabled', live: 'reassignment_planned' }[L.mode];
else if (B.counts.heldOwners) outcome = 'held_no_coverage';
else if (B.counts.pendingOwners) outcome = 'pending_grace_period';
else outcome = 'no_open_records_on_deactivated_owners';
return [{ json: {
  workflow: 'n8n-hubspot-owner-deactivation-lead-reassignment-sentinel', runId: cfg.runId, executionMode: cfg.executionMode, finishedAt: new Date().toISOString(), outcome,
  safety: { sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun, reassignmentEnabled: cfg.reassignmentEnabled, sendSlackAlerts: cfg.sendSlackAlerts, webhookEnabled: cfg.webhookEnabled,
    maxReassignmentsPerRun: cfg.maxReassignmentsPerRun, massDeactivationThreshold: cfg.massDeactivationThreshold, gracePeriodHours: cfg.gracePeriodHours },
  status: B.status, error: B.error, counts: B.counts, massGuard: B.massGuard, warnings: B.warnings,
  owners: B.owners.map((o) => ({ ownerId: o.ownerId, source: o.source, state: o.state, deactivatedAt: o.deactivatedAt, openRecords: o.openRecords, notes: o.notes,
    objects: Object.fromEntries(Object.entries(o.objects).map(([t, x]) => [t, { open: x.openCount, remaining: x.remaining, filteredOut: x.filteredOut, error: x.error, route: x.route ? { level: x.route.level, pool: x.route.pool } : null }])) })),
  excludedOwners: B.excludedOwners,
  reassignments: (R ? R.assignments : B.assignments.map((a) => ({ ...a, result: 'planned' }))).map((a) => ({ objectType: a.objectType, recordId: a.recordId, from: a.fromOwnerId, to: a.toOwnerId, route: a.level, result: a.result })),
  deferred: B.deferred, failures: R ? R.failures : [], rollback: B.rollback,
  slack: sl ? { sent: sl.sent, failed: sl.failed, error: sl.error } : { sent: 0, alert: L.alert },
  runSummaryWebhook: wh, stateRecorded: S.recorded,
} }];
